import{_ as a,a0 as r,w as u,s as p,ao as o,I as e,x as l,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux 内核测试与调试（3） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 内核测试与调试（3） | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 内核测试与调试（3） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 内核测试与调试（3） | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140718 Linux Kernel Testing and Debugging 3","title":"Linux 内核测试与调试（3）","tag":"201408","desc":""},"relativePath":"201408/20140718 Linux Kernel Testing and Debugging 3.md","filePath":"[post].md"}'),d={name:"201408/20140718 Linux Kernel Testing and Debugging 3.md"};function g(f,t,m,b,k,T){const i=r("Link");return u(),p("div",null,[t[16]||(t[16]=o('<h1 id="linux-内核测试与调试-3" tabindex="-1">Linux 内核测试与调试（3） <a class="header-anchor" href="#linux-内核测试与调试-3" aria-label="Permalink to “Linux 内核测试与调试（3）”">​</a></h1><h3 id="基本测试" tabindex="-1">基本测试 <a class="header-anchor" href="#基本测试" aria-label="Permalink to “基本测试”">​</a></h3><p>安装好内核后，试试能不能启动它。能启动的话，检查 dmesg 看看有没有隐藏的错误。试试下面的功能：</p><ul><li>网络（Wifi 或者网线）是否可用？</li><li>ssh 是否可用？</li><li>使用 ssh 远程传输文件。</li><li>使用 git clone 和 git pull 命令。</li><li>用用网络浏览器。</li><li>查看 email。</li><li>使用 ftp, wget 等软件下载文件。</li><li>播放音频视频文件。</li><li>连上 USB 鼠标等设备。</li></ul><h3 id="检查内核日志" tabindex="-1">检查内核日志 <a class="header-anchor" href="#检查内核日志" aria-label="Permalink to “检查内核日志”">​</a></h3><p>使用 dmesg 查看隐藏的问题，对于定位新代码带来的 bug 是一个好方法。一般来说，dmesg 不会输出新的 crit, alert, emerg 级别的错误信息，也不应该出现新的 err 级别的信息。你要注意的是那些 warn 级别的日志信息。请注意 warn 这个级别的信息并不是坏消息，新代码带来新的警告信息，不会给内核带去严重的影响。</p><ul><li>dmesg -t -l emerg</li><li>dmesg -t -l crit</li><li>dmesg -t -l alert</li><li>dmesg -t -l err</li><li>dmesg -t -l warn</li><li>dmesg -t -k</li><li>dmesg -t</li></ul>',7)),e("p",null,[t[1]||(t[1]=l("下面的脚本运行了上面的命令，并且将输出保存起来，以便与老的内核的 dmesg 输出作比较（LCTT：老内核的 dmesg 输出在本系列的",-1)),n(i,{href:"http://linux.cn/article-3629-1.html"},{default:s(()=>[...t[0]||(t[0]=[l("第二篇文章",-1)])]),_:1}),t[2]||(t[2]=l("中有介绍）。然后运行 diff 命令，查看新老内核 dmesg 日志之间的不同。这个脚本需要输入老内核版本号，如果不输入参数，它只会生成新内核的 dmesg 日志文件后直接退出，不再作比较（LCTT：话是这么说没错，但点开脚本一看，没输参数的话，这货会直接退出，连新内核的 dmesg 日志也不会保存的）。如果 dmesg 日志有新的警告信息，表示新发布的内核有漏网之“虫”，这些 bug 逃过了自测和系统测试。你要看看，那些警告信息后面有没有栈跟踪信息？也许这里有很多问题需要你进一步调查分析。",-1))]),e("ul",null,[e("li",null,[n(i,{href:"http://linuxdriverproject.org/mediawiki/index.php/Dmesg_regression_check_script"},{default:s(()=>[...t[3]||(t[3]=[e("strong",null,"dmesg 测试脚本",-1)])]),_:1})])]),t[17]||(t[17]=e("h3",{id:"压力测试",tabindex:"-1"},[l("压力测试 "),e("a",{class:"header-anchor",href:"#压力测试","aria-label":"Permalink to “压力测试”"},"​")],-1)),t[18]||(t[18]=e("p",null,"执行压力测试的一个好办法是同时跑三四个内核编译任务。下载各种版本的内核，同时编译它们，并记录时间。比较新内核跑压力测试和老内核跑压力测试所花的时间，然后可以定位新内核的性能。如果新内核跑压力测试的时间比老内核的更长，说明新内核的部分模块性能退步了。性能问题很难调试出来。第一步是找出哪里导致的性能退步。同时跑多个内核编译任务对检测内核整体性能来说是个好方法，但是这种方法涵盖了多个内核模块，比如内存管理、文件系统、DMA、驱动等（LCTT：也就是说，这种压力测试没办法定位到是哪个模块造成了性能的下降）。",-1)),t[19]||(t[19]=e("pre",null,[e("code",null,`time make all
`)],-1)),t[20]||(t[20]=e("h3",{id:"内核测试工具",tabindex:"-1"},[l("内核测试工具 "),e("a",{class:"header-anchor",href:"#内核测试工具","aria-label":"Permalink to “内核测试工具”"},"​")],-1)),t[21]||(t[21]=e("p",null,"我们可以在 Linux 内核本身找到多种测试方法。下面介绍一个很好用的功能测试工具集： ktest 套件",-1)),t[22]||(t[22]=e("p",null,"ktest 是一个自动测试套件，它可以提供编译安装启动内核一条龙测试服务，也可以跑交叉编译测试，前提是你的系统有安装交叉编译所需要的软件。ktest 依赖于 flex 和 bison。详细信息请参考放在 tools/testing/ktest 目录下的文档，你可以自学成材。另外还有一些参考资料教你怎么使用 ktest：",-1)),e("ul",null,[e("li",null,[n(i,{href:"http://elinux.org/Ktest#Git_Bisect_type"},{default:s(()=>[...t[4]||(t[4]=[e("strong",null,"ktest-eLinux.org",-1)])]),_:1})])]),t[23]||(t[23]=o(`<h3 id="tools-testing-selftests-套件" tabindex="-1">tools/testing/selftests 套件 <a class="header-anchor" href="#tools-testing-selftests-套件" aria-label="Permalink to “tools/testing/selftests 套件”">​</a></h3><p>我们来玩玩自测吧。内核源码的多个子系统都有自己的自测工具，到目前为止，断点、cpu热插拔、efivarfs、IPC、KCMP、内存热插拔、mqueue、网络、powerpc、ptrace、rcutorture、定时器和虚拟机子系统都有自测工具。另外，用户态内存的自测工具可以利用 test_user_copy 模块来测试用户态内存到内核态的拷贝过程。下面的命令演示了如何使用这些测试工具：</p><p>编译测试：</p><pre><code>make -C tools/testing/selftests 
</code></pre><p>测试全部：（有些测试需要 root 权限，你需要以 root 用户登入系统然后运行命令）</p><pre><code>make -C tools/testing/selftests run_tests 
</code></pre><p>只测试单个子系统：</p><pre><code>make -C tools/testing/selftests TARGETS=vm run_tests 
</code></pre><h3 id="tools-testing-fault-injection-套件" tabindex="-1">tools/testing/fault-injection 套件 <a class="header-anchor" href="#tools-testing-fault-injection-套件" aria-label="Permalink to “tools/testing/fault-injection 套件”">​</a></h3><p>在 tools/testing 目录下的另一个测试套件是 fault-injection。failcmd.sh 脚本用于检测 slab 和内存页分配器的错误。这些工具可以测试内核能否很好地从错误状态中恢复回来。这些测试需要用到 root 权限。下面简单介绍了一些当前能提供的错误检测方法。随着错误检测方法的增加，这份名单也会不断增长。最新的名单请参考 Documentation/fault-injection/fault-injection.txt 文档。</p><p>failslab （默认选项）</p><blockquote><p>产生 slab 分配错误。作用于 kmalloc(), kmem_cache_alloc() 等函数（LCTT：产生的结果是调用这些函数就会返回失败，可以模拟程序分不到内存时是否还能稳定运行下去）。</p></blockquote><p>fail_page_alloc</p><blockquote><p>产生内存页分配的错误。作用于 alloc_pages(), get_free_pages() 等函数（LCTT：同上，调用这些函数，返回错误）。</p></blockquote><p>fail_make_request</p><blockquote><p>对满足条件（可以设置 /sys/block//make-it-fail 或 /sys/block///make-it-fail 文件）的磁盘产生 IO 错误，作用于 generic_make_request() 函数（LCTT：所有针对这块磁盘的读或写请求都会出错）。</p></blockquote><p>fail_mmc_request</p><blockquote><p>对满足条件（可以设置 /sys/kernel/debug/mmc0/fail_mmc_request 这个 debugfs 属性）的磁盘产生 MMC 数据错误。</p></blockquote><p>你可以自己配置 fault-injection 套件的功能。fault-inject-debugfs 内核模块在系统运行时会在 debugfs 文件系统下面提供一些属性文件。你可以指定出错的概率，指定两个错误之间的时间间隔，当然本套件还能提供更多其他功能，具体请查看 Documentation/fault-injection/fault-injection.txt。 Boot 选项可以让你的系统在 debugfs 文件系统起来之前就可以产生错误，下面列出几个 boot 选项：</p><ul><li>failslab=</li><li>fail_page_alloc=</li><li>fail_make_request=</li><li>mmc_core.fail_request=[interval],[probability],[space],[times]</li></ul><p>fault-injection 套件提供接口，以便增加新的功能。下面简单介绍下增加新功能的步骤，详细信息请参考上面提到过的文档：</p><p>使用 DECLARE_FAULT_INJECTION(name) 定义默认属性；</p><blockquote><p>详细信息可查看 fault-inject.h 中定义的 struct fault_attr 结构体。</p></blockquote><p>配置 fault 属性，新建一个 boot 选项;</p><blockquote><p>这步可以使用 setup_fault_attr(attr, str) 函数完成，为了能在系统启动的早期产生错误，添加一个 boot 选项这一步是必须要有的。</p></blockquote><p>添加 debugfs 属性；</p><blockquote><p>使用 fault_create_debugfs_attr(name, parent, attr) 函数，为新功能添加新的 debugfs 属性。</p></blockquote><p>为模块设置参数；</p><blockquote><p>为模块添加一些参数，对于配置错误属性来说是一个好主意，特别是当新功能的应用范围受限于单个内核模块的时候（LCTT：不同内核，你的新功能可能需要不同的测试参数，通过设置参数，你的功能可以不必为了迎合不同内核而每次都重新编译一遍）。</p></blockquote><p>添加一个钩子函数到错误测试的代码中。</p><blockquote><p>should_fail(attr, size) —— 当这个钩子函数返回 true 时，用户的代码就应该产生一个错误。</p></blockquote><p>应用程序使用这个 fault-injection 套件可以指定某个具体的内核模块产生 slab 和内存页分配的错误，这样就可以缩小性能测试的范围。</p><hr>`,33)),e("p",null,[t[6]||(t[6]=l("via: ",-1)),n(i,{href:"http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,2"},{default:s(()=>[...t[5]||(t[5]=[l("http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,2",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=l("译者：",-1)),n(i,{href:"https://github.com/bazz2"},{default:s(()=>[...t[7]||(t[7]=[l("bazz2",-1)])]),_:1}),t[10]||(t[10]=l(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=l("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[l("LCTT",-1)])]),_:1}),t[14]||(t[14]=l(" 原创翻译，",-1)),n(i,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[l("Linux中国",-1)])]),_:1}),t[15]||(t[15]=l(" 荣誉推出",-1))])])}const L=a(d,[["render",g]]);export{C as __pageData,L as default};
